 let hits=0;const inArc=(ex,ey,r)=>{const dist=Math.hypot(ex,ey);return dist<r&&(dist<30||(ex*ux+ey*uy)/(dist||1)>(combo===3?-.12:.1));};
 if(game.inHub&&room.dummy&&inArc(room.dummy.x+room.dummy.w/2-cx,room.dummy.y+room.dummy.h/2-cy,range))hitDummy(room,damage,p.face);for(const e of room.enemies){const ex=e.x+e.w/2-cx,ey=e.y+e.h/2-cy;if(e.alive&&inArc(ex,ey,range)){hitEnemy(room,e,damage,'melee');e.x=clamp(e.x+p.face*(combo===3?34:18),WALL+10,W-WALL-e.w-10);e.vx=p.face*210;e.vy=Math.min(e.vy,-105);hits++;}}
 for(const q of room.portals){const ex=q.x-cx,ey=q.y-cy;if(q.alive&&inArc(ex,ey,range))hitPortal(room,q,damage);}
 for(const c of room.crystals)if(c.alive&&Math.hypot(c.x-cx,c.y-cy)<range){c.hp-=damage;c.flash=.2;if(c.hp<=0)explodeCrystal(room,c);}
 for(const b of room.breakables)if(b.alive&&inArc(b.x+b.w/2-cx,b.y+b.h/2-cy,range)){hitBreakable(room,b,damage);}
 for(const o of room.props)if(o.alive&&inArc(o.x+o.w/2-cx,o.y+o.h/2-cy,range))hitProp(room,o,damage);
