function drawGenerator(g){ctx.save();ctx.fillStyle=g.failed?'#66535a':'#2f6274';ctx.fillRect(g.x-28,g.y-35,56,39);ctx.fillStyle=g.failed?'#a44f59':'#74e7cb';ctx.fillRect(g.x-17,g.y-28,34,25);ctx.strokeStyle='#d9e8ff';ctx.strokeRect(g.x-28,g.y-35,56,39);ctx.fillStyle='#0b1727';ctx.fillRect(g.x-36,g.y-51,72,8);ctx.fillStyle=g.failed?'#aa616c':'#83efbd';ctx.fillRect(g.x-34,g.y-49,68*g.hp/g.maxHp,4);ctx.textAlign='center';ctx.font='bold 10px monospace';ctx.fillStyle='#f5e9c2';ctx.fillText(g.failed?'JENERATÖR KAYIP':g.time>0?'KORU '+Math.ceil(g.time)+'sn':'KORUNDU',g.x,g.y-59);ctx.restore();}
