function drawProp(o){ctx.save();ctx.translate(o.x,o.y);ctx.fillStyle=o.hit>0?'#ffffff':o.kind==='crystal'?'#69b6d1':'#947453';ctx.fillRect(0,0,o.w,o.h);ctx.strokeStyle=o.kind==='crystal'?'#b7f8ff':'#d2b38a';ctx.lineWidth=3;ctx.strokeRect(2,2,o.w-4,o.h-4);ctx.beginPath();ctx.moveTo(3,3);ctx.lineTo(o.w-3,o.h-3);ctx.moveTo(o.w-3,3);ctx.lineTo(3,o.h-3);ctx.stroke();ctx.restore();}
function drawLoot(item){
 ctx.save();ctx.translate(item.x,item.y);if(item.kind){if(item.kind==='gold'){ctx.shadowColor='#ffe187';ctx.shadowBlur=17;ctx.fillStyle='#ffc54d';ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff7c9';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#765126';ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText('G',0,4);ctx.restore();return;}if(item.kind==='mod'){ctx.shadowColor='#f9dc85';ctx.shadowBlur=18;ctx.fillStyle='#e8c66f';ctx.fillRect(-12,-12,24,24);ctx.fillStyle='#293d57';ctx.fillRect(-7,-2,14,4);ctx.fillRect(-2,-7,4,14);ctx.restore();return;}if(item.kind==='artifact'){ctx.shadowColor='#cfa5ff';ctx.shadowBlur=18;ctx.fillStyle=ACCESSORIES[item.artifact]?.color||'#bf9aff';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(15,0);ctx.lineTo(0,16);ctx.lineTo(-15,0);ctx.closePath();ctx.fill();ctx.restore();return;}ctx.shadowBlur=14;ctx.shadowColor=item.kind==='health'?'#73f3a0':item.kind==='grenade'?'#ffa56f':'#ffdf89';ctx.fillStyle=item.kind==='health'?'#62dd90':item.kind==='grenade'?'#ed8c68':'#f4bf64';ctx.fillRect(-12,-12,24,24);ctx.fillStyle='#25303c';if(item.kind==='health'){ctx.fillRect(-3,-9,6,18);ctx.fillRect(-9,-3,18,6);}else if(item.kind==='grenade'){ctx.fillRect(-2,-9,4,5);ctx.fillRect(-7,-4,14,13);}else{ctx.fillRect(-7,-5,5,13);ctx.fillRect(2,-5,5,13);}ctx.restore();return;}ctx.shadowBlur=10;ctx.shadowColor='#eebf72';const img=WEAPON_SPRITES[item.weapon];if(img instanceof HTMLCanvasElement){ctx.imageSmoothingEnabled=false;ctx.drawImage(img,-29,-17,58,29);}else{ctx.fillStyle='#c2cbd6';ctx.fillRect(-20,-7,36,9);}ctx.restore();
 if(item.grounded&&currentRoom().interact?.nearbyLoot===item){ctx.fillStyle='#ffe4a9';ctx.font='bold 12px monospace';ctx.fillText('E · '+weaponName(item.weapon)+' AL',item.x-50,item.y-29);}
}
function drawCrosshair(){if(game?.player?.reloadTime>0){const p=game.player,progress=1-p.reloadTime/Math.max(.01,p.reloadDuration),t=performance.now()/1000;ctx.save();ctx.strokeStyle='#ffd572';ctx.lineWidth=4;ctx.shadowColor='#ffbe55';ctx.shadowBlur=13;ctx.beginPath();ctx.arc(mouse.x,mouse.y,20,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);ctx.stroke();ctx.shadowBlur=0;for(let i=0;i<4;i++){const a=t*3+i*Math.PI/2;ctx.fillStyle='#ffcf7e';ctx.fillRect(mouse.x+Math.cos(a)*27-2,mouse.y+Math.sin(a)*27-2,4,4);}ctx.restore();}ctx.strokeStyle='#fff2cd';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(mouse.x,mouse.y,8,0,Math.PI*2);ctx.moveTo(mouse.x-15,mouse.y);ctx.lineTo(mouse.x-10,mouse.y);ctx.moveTo(mouse.x+10,mouse.y);ctx.lineTo(mouse.x+15,mouse.y);ctx.moveTo(mouse.x,mouse.y-15);ctx.lineTo(mouse.x,mouse.y-10);ctx.moveTo(mouse.x,mouse.y+10);ctx.lineTo(mouse.x,mouse.y+15);ctx.stroke();}
function drawGameHud(){const room=currentRoom();if(game.inHub){ctx.save();ctx.fillStyle='#142846e8';ctx.fillRect(245,16,665,39);ctx.strokeStyle='#8fbbeb';ctx.strokeRect(245,16,665,39);ctx.fillStyle='#ecdfaa';ctx.textAlign='center';ctx.font='900 14px monospace';ctx.fillText('HAZIRLIK · E: ATÖLYE  |  KUKLA: SİLAH TESTİ  |  E: PORTAL',W/2+17,41);ctx.restore();return;}const flow=game.flow||0;ctx.fillStyle='#102033';ctx.fillRect(16,67,190,13);ctx.fillStyle=flow>70?'#ffe097':'#7de1bd';ctx.fillRect(18,69,186*flow/100,9);ctx.strokeStyle='#91b5cc';ctx.strokeRect(16,67,190,13);ctx.textAlign='left';ctx.font='bold 10px monospace';ctx.fillStyle='#e5ffe9';ctx.fillText('FORGE FLOW '+Math.round(flow)+'%',18,63);if(!room.cleared){ctx.fillStyle='#e9a0a0';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText('⚔ ARENA KİLİTLİ · '+room.portals.filter(q=>q.alive).length+' PORTAL · '+room.enemies.length+' DÜŞMAN',W/2,59);ctx.textAlign='left';}if(room.generator){ctx.textAlign='center';ctx.font='bold 12px monospace';ctx.fillStyle=room.generator.failed?'#ff928d':'#a7f5c2';ctx.fillText(room.generator.failed?'SAVUNMA BAŞARISIZ':'JENERATÖR '+room.generator.hp+' CAN · '+Math.ceil(room.generator.time)+'sn',W/2,79);ctx.textAlign='left';}if(room.type==='hunt'&&!room.cleared){ctx.font='bold 12px monospace';ctx.fillStyle='#ffe09c';ctx.textAlign='center';ctx.fillText(room.enemies.some(e=>e.hunted&&e.alive)?'HEDEFİ YOK ET · PORTALLARI KAPAT':'HEDEF DÜŞTÜ · DÜŞMANLARI TEMİZLE',W/2,79);ctx.textAlign='left';}if(room.type==='boss'&&room.enemies.length){ctx.textAlign='center';ctx.font='bold 12px monospace';ctx.fillStyle='#ffcf99';ctx.fillText('BOSS '+room.bossStage+'/4 · '+BIOMES[room.biome].name+' · LV '+room.level,W/2,101);ctx.textAlign='left';let e=room.enemies.find(e=>e.type==='boss');if(e){ctx.fillStyle='#1b1524';ctx.fillRect(290,83,540,12);ctx.fillStyle='#b57db9';ctx.fillRect(290,83,540*(e.hp/e.maxHp),12);ctx.strokeStyle='#cda5c8';ctx.strokeRect(290,83,540,12);}}}
function updateHud(){
 if(!game)return;const p=game.player;
 $('hpFill').style.width=(p.hp/p.maxHp*100)+'%';$('hpText').textContent=p.hp+' / '+p.maxHp;
 $('weaponLabel').textContent=weaponName(p.weapon);$('weaponTypeLabel').textContent=weaponType(p.weapon);
 $('hudXp').innerHTML=p.weapon===null?'':xpBarHTML(p.weapon);
 $('ammoText').textContent=p.weapon===null?'—':p.ammo+' / '+p.reserve+' · UST '+masteryLevel(p.weapon);
 $('roomLabel').textContent=game.inHub?'HAZIRLIK':String(game.roomId+1).padStart(2,'0')+' / '+game.rooms.length;
 $('goldLabel').textContent=p.gold;
 for(let i=0;i<2;i++){const slot=p.slots[i];renderQuickSlot(i+1,slot?{weapon:slot.weapon,name:weaponName(slot.weapon),sub:slot.ammo+' / '+slot.reserve+' MERMİ',selected:p.activeSlot===i}:{name:'BOŞ SİLAH',sub:'Silah yok',empty:true});}
 renderQuickSlot(3,{name:'SAĞLIK KİTİ',sub:p.kits?'Kullanıma hazır':'Stokta yok',count:p.kits+'/5',icon:'kit',empty:!p.kits});
 renderQuickSlot(4,{name:'EL BOMBASI',sub:p.grenades?'Atışa hazır':'Stokta yok',count:p.grenades+'/3',icon:'grenade',empty:!p.grenades});
 const a=p.accessories[0];renderQuickSlot(5,a?{name:ACCESSORIES[a.type].name,sub:a.cooldown>0?'BEKLE '+Math.ceil(a.cooldown)+'sn':'HAZIR',count:'1',icon:a.type,selected:p.activeAccessory===a.type&&p.accessoryTime>0}:{name:'ÖZEL EŞYA',sub:'Boş',icon:'empty',empty:true});
}
function showEnd(won){$('gamePauseMenu').classList.add('hidden');$('pause').classList.remove('hidden');$('pause').querySelector('.eyebrow').textContent=won?'MAĞARA TEMİZLENDİ':'MACERA SONA ERDİ';$('pause').querySelector('h1').innerHTML=won?'ZAFER <em>!</em>':'OYUN <em>BİTTİ</em>';$('pause').querySelector('p').textContent='Altın: '+game.player.gold+' · Yenilen düşman: '+game.player.kills+' · Keşfedilen oda: '+game.rooms.filter(r=>r.visited).length+'/'+game.rooms.length;$('startBtn').textContent='YENİ OYUN →';$('seedInput').value=String(game.seed);$('forgePanel').classList.remove('hidden');refreshForge();}
let loadoutOpen=false,levelToastTime=0;
function levelUpToast(weapon,level){const el=$('levelToast');el.textContent='★ SİLAH USTALIĞI ARTTI ★\n'+weaponName(weapon)+' · SEVİYE '+level+(level===2||level===4||level===6||level===8?'\nYENİ EKLENTİ YUVASI AÇILDI!':'');el.classList.remove('hidden');levelToastTime=3.2;sound(790,.18,'triangle',.035);}
function statRow(label,base,value,unit='',digits=0,lowerBetter=false){const fmt=n=>Number(n).toFixed(digits),changed=Math.abs(value-base)>0.00001,delta=value-base,sign=delta>0?'+':'−';return '<div class="weaponStatRow"><span>'+label+'</span><b>'+fmt(value)+unit+'</b>'+(changed?'<small class="'+((lowerBetter?delta<0:delta>0)?'statBuff':'statNerf')+'">'+fmt(base)+unit+' '+sign+fmt(Math.abs(delta))+unit+'</small>':'<small class="statBase">TEMEL '+fmt(base)+unit+'</small>')+'</div>';}
function weaponStatHTML(slot){const st=weaponStats(slot),mods=slot.mods||[],synergies=[];
 if(st.family==='explosive'&&mods.includes('stabilizer'))synergies.push('DENGELEYİCİ + PATLAYICI → PATLAMA ALANI +%25');
 if(st.family==='arc'&&mods.includes('core'))synergies.push('FAZ ÇEKİRDEĞİ + ARK → ALAN HASARI +%50');
 if(mods.includes('shockCore'))synergies.push('ŞOK → ATIŞ BAŞINA EN FAZLA 1 YAKIN HEDEFE %35 ZİNCİR HASARI');
 if(mods.includes('burnCore'))synergies.push('YANMA → 3 SN BOYUNCA HER 0,5 SN %12 MERMİ HASARI');
 return '<div class="weaponStats"><div class="weaponStatsHeading">ANLIK SİLAH ÖZELLİKLERİ</div>'+statRow('HASAR / MERMİ',st.baseDamage,st.damage)+statRow('TAM İSABET',st.baseShotDamage,st.shotDamage)+statRow('TEORİK DPS',st.baseDps,st.dps,'',1)+statRow('ATEŞ / SN',st.baseFireRate,st.fireRate,'',2)+statRow('DOLDURMA',st.baseReload,st.reload,' sn',2,true)+statRow('MERMİ HIZI',st.baseSpeed,st.speed,'',0)+statRow('DELME',st.basePierce,st.pierce)+statRow('SAÇILMA',100,st.spread*100,'%',0,true)+statRow('ŞARJÖR',st.baseMag,st.mag)+statRow('MERMİ TASARRUFU',0,st.ammoSave*100,'%')+statRow('HAREKET HASARI',13,st.movementBonus*100,'%')+statRow('GERİ TEPME',100,st.recoil*100,'%',0,true)+(['explosive','plasma','arc'].includes(st.family)?statRow('ETKİ ALANI',100,st.areaBonus*100,'%'): '')+statRow('SARSILMA',100,st.staggerBonus*100,'%')+(synergies.length?'<div class="synergyNote">'+synergies.join('<br>')+'</div>':'')+'<small class="statExplanation">DPS: yeniden doldurma, isabet ve özel etkiler hariç. Hareket bonusu yalnızca dash / kanca / duvar zıplaması sonrası geçerli.</small></div>';}
function enemyCodexHTML(){return '<section class="bagCard enemyCodex"><h3>DÜŞMAN REHBERİ · 5 ROL / 4 BİYOM</h3><p>Tank, uçan menzilli, büyücü, şifacı ve boss. Her biyomda farklı görünüm ve isimleri vardır. Şifacılar nadir çıkar; boss yalnızca boss odasındadır.</p>'+Object.entries(BIOMES).map(([key,b])=>'<div class="codexBiome"><strong>'+b.name+'</strong><div>'+['red','blue','purple','healer','boss'].map(role=>'<span>'+VARIANTS[key][role]+' <small>'+({red:'TANK',blue:'UÇAN',purple:'BÜYÜCÜ',healer:'ŞİFACI',boss:'BOSS'})[role]+'</small></span>').join('')+'</div></div>').join('')+'</section>';}
function renderLoadout(){if(!game)return;saveSlot();const p=game.player,root=$('loadoutContent');root.innerHTML='';for(let i=0;i<2;i++){const w=p.slots[i],card=document.createElement('section');card.className='gunCard';if(!w){card.innerHTML='<h3>SİLAH '+(i+1)+' · BOŞ</h3><p>Bu slotta silah bulunmuyor.</p>';root.append(card);continue;}const picture=WEAPON_SPRITES[w.weapon].toDataURL('image/png');card.innerHTML='<h3>SİLAH '+(i+1)+' · '+weaponType(w.weapon)+'</h3><div class="gunVisual"><img alt="'+weaponName(w.weapon)+' piksel silah görseli" src="'+picture+'"><div><strong>'+weaponName(w.weapon)+'</strong><small>'+PROJECTILE_FAMILIES[WEAPON_PROJECTILES[w.weapon]].name+' · '+w.ammo+'/'+w.reserve+' MERMİ</small>'+xpBarHTML(w.weapon)+'</div></div>'+weaponStatHTML(w);for(let j=0;j<4;j++){const row=document.createElement('label');row.className='modRow'+(j>=getModSlots(w.weapon)?' locked':'');const select=document.createElement('select');select.dataset.weaponSlot=String(i);select.dataset.modSlot=String(j);select.disabled=j>=getModSlots(w.weapon);const current=w.mods[j]||'';let options='<option value="">'+(select.disabled?'KİLİTLİ · SEV '+([2,4,6,8][j]):'BOŞ EKLENTİ')+'</option>';for(const [id,spec] of Object.entries(MODS)){if(spec.slot===j&&(id===current||game.stashedMods.includes(id)))options+='<option value="'+id+'" '+(id===current?'selected':'')+'>'+modNameForWeapon(w.weapon,id)+(id===current?' · TAKILI':' · ÇANTADA')+'</option>';}select.innerHTML=options;row.innerHTML='<span>'+FORGE_SLOT_LABELS[j]+'</span>';row.append(select);const hint=document.createElement('small');hint.className='modBagHint';hint.textContent=current?modEffectForWeapon(w.weapon,current):j>=getModSlots(w.weapon)?'Ustalık '+[2,4,6,8][j]+' gerekli.':'Boş yuva · Eklentini çantadan seç.';row.append(hint);card.append(row);}root.append(card);}const bag=document.createElement('section');bag.className='bagCard';bag.innerHTML='<h3>ÇANTA · EŞYALAR &amp; EKLENTİLER</h3><div class="bagItems"></div>';const bagItems=bag.querySelector('.bagItems');const pieces=['SAĞLIK KİTİ ×'+p.kits,'BOMBA ×'+p.grenades,'MERMİ KUTUSU ×'+p.ammoBoxes,...p.accessories.filter(Boolean).map(a=>ACCESSORIES[a.type].name),...game.stashedMods.map(m=>MODS[m]?.name||m)];for(const name of pieces){const chip=document.createElement('span');chip.className='bagChip';chip.textContent=name;bagItems.append(chip);}if(!game.stashedMods.length){const chip=document.createElement('span');chip.className='bagChip';chip.textContent='BOŞTA EKLENTİ YOK';bagItems.append(chip);}root.append(bag);root.insertAdjacentHTML('beforeend',enemyCodexHTML());}
function switchModFromBag(select){if(!game)return;const i=Number(select.dataset.weaponSlot),j=Number(select.dataset.modSlot),w=game.player.slots[i],next=select.value,old=w?.mods[j]||'';if(!w||j>=getModSlots(w.weapon)||next===old)return;if(next&&(!MODS[next]||masteryLevel(w.weapon)<MODS[next].level||!game.stashedMods.includes(next)||MODS[next].slot!==j||w.mods.includes(next))){renderLoadout();return;}if(next)game.stashedMods.splice(game.stashedMods.indexOf(next),1);if(old)game.stashedMods.push(old);w.mods[j]=next||undefined;const cap=weaponStats(w).mag;if(w.ammo>cap){w.reserve=Math.min(AMMO_MAX[w.weapon],w.reserve+w.ammo-cap);w.ammo=cap;}if(game.player.activeSlot===i){game.player.ammo=w.ammo;game.player.reserve=w.reserve;}renderLoadout();updateHud();}
function toggleLoadout(force){if(shopOpen||hubForgeOpen||helpOpen||!game||game.dead||game.won)return;const show=typeof force==='boolean'?force:!loadoutOpen;loadoutOpen=show;$('loadoutOverlay').classList.toggle('hidden',!show);if(show){if(mapOpen)setMap(false);paused=true;$('gamePauseMenu').classList.add('hidden');$('pause').classList.add('hidden');renderLoadout();}else{paused=false;canvas.focus();}}
$('loadoutContent').addEventListener('change',e=>{if(e.target.matches('select[data-weapon-slot]'))switchModFromBag(e.target);});$('loadoutBtn').onclick=()=>toggleLoadout();$('pauseLoadoutBtn').onclick=()=>toggleLoadout(true);$('closeLoadout').onclick=()=>toggleLoadout(false);
function openHelp(){if(!game||paused||helpOpen||shopOpen||hubForgeOpen||loadoutOpen||mapOpen||game.dead||game.won)return;helpOpen=true;paused=true;mouse.down=false;$('helpOverlay').classList.remove('hidden');}
function closeHelp(){if(!helpOpen)return;helpOpen=false;$('helpOverlay').classList.add('hidden');paused=false;canvas.focus();}
$('closeHelp').onclick=closeHelp;
function togglePause(){if(helpOpen){closeHelp();return;}if(shopOpen){closeShop();return;}if(loadoutOpen){toggleLoadout(false);return;}if(hubForgeOpen){closeHubForge();return;}if(!game||game.dead||game.won)return;paused=!paused;$('gamePauseMenu').classList.toggle('hidden',!paused);if(!paused)canvas.focus();}
function returnToMainMenu(){if(!game)return;saveSlot();const seed=game.seed;buildGame(seed);setupHub();}
$('resumeGameBtn').onclick=()=>togglePause();$('muteGameBtn').onclick=()=>{muted=!muted;$('muteGameBtn').textContent=muted?'♪ SESİ AÇ':'♪ SESİ KAPAT';};$('mainMenuBtn').onclick=()=>returnToMainMenu();
function drawMap(){
 if(!game)return;const c=mctx,w=mapCanvas.width,h=mapCanvas.height;c.clearRect(0,0,w,h);c.fillStyle='#0b111c';c.fillRect(0,0,w,h);
 const rooms=game.rooms,minX=Math.min(...rooms.map(r=>r.x)),maxX=Math.max(...rooms.map(r=>r.x)),minY=Math.min(...rooms.map(r=>r.y)),maxY=Math.max(...rooms.map(r=>r.y));
 const step=Math.min(55,(w-125)/(maxX-minX+1),(h-130)/(maxY-minY+1)),ox=(w-(maxX-minX)*step)/2+20,oy=71+(h-130-(maxY-minY)*step)/2;
 const zoneColors=['rgba(98,149,184,.16)','rgba(82,164,106,.16)','rgba(159,101,203,.16)','rgba(211,109,76,.16)'];
 const zoneNames=['I · TERK EDİLMİŞ MADEN · LV 1','II · ZEHİRLİ ORMAN · LV 2','III · MOR KRİSTAL · LV 3','IV · LAV ÇEKİRDEĞİ · LV 3'];
 for(let zone=0;zone<4;zone++){const top=zone===0?oy-step*.6:oy+step*(zone*5+.5),bottom=oy+step*(zone*5+5.5);
 c.fillStyle=zoneColors[zone];c.fillRect(5,top,w-10,bottom-top);
 c.fillStyle=['#b2d9f4','#aeefbb','#dec0ff','#ffc39f'][zone];c.font='bold 11px monospace';c.textAlign='left';c.fillText(zoneNames[zone],11,top+17);
 if(zone<3){c.strokeStyle='#a5bcd8';c.lineWidth=1;c.setLineDash([6,5]);c.beginPath();c.moveTo(7,bottom);c.lineTo(w-7,bottom);c.stroke();c.setLineDash([]);}
 }
 for(const room of rooms)for(const id of Object.values(room.links)){const next=rooms[id];if(id<=room.id)continue;c.strokeStyle=room.visited&&next.visited?'#6dcfae':'#354355';c.lineWidth=room.visited&&next.visited?4:2;c.setLineDash(room.visited&&next.visited?[]:[4,4]);c.beginPath();c.moveTo(ox+(room.x-minX)*step,oy+(room.y-minY)*step);c.lineTo(ox+(next.x-minX)*step,oy+(next.y-minY)*step);c.stroke();}c.setLineDash([]);
 for(const room of rooms){const x=ox+(room.x-minX)*step,y=oy+(room.y-minY)*step,sz=Math.max(12,step*(room.type==='boss'?1.18:.67)),known=room.discovered||room.visited,active=room.id===game.roomId;
 c.fillStyle=active?'#fff0a4':room.cleared?'#66c89e':room.visited?'#75a8d9':known?(room.type==='boss'?'#a77ebc':'#647c99'):'#263244';
 c.fillRect(x-sz/2,y-sz/2,sz,sz);c.strokeStyle=active?'#ffffff':known?'#afc0d2':'#47546a';c.lineWidth=active?3:1;c.strokeRect(x-sz/2,y-sz/2,sz,sz);
 c.textAlign='center';c.fillStyle=active?'#182235':known?'#f6f0de':'#79899b';c.font='bold '+Math.max(8,Math.min(12,step*.25))+'px monospace';
 c.fillText(active?'●':known?room.type==='boss'?'B'+room.bossStage:({defense:'K',hunt:'H',elite:'E',treasure:'T'})[room.type]||'·':'?',x,y+4);
 if(known&&room.type!=='boss'&&room.type!=='start'){c.fillStyle='#b9f4ca';c.font='bold 9px monospace';c.fillText(({ammo:'M',mod:'E',xp:'XP',health:'C'})[room.reward]||'',x,y+sz/2+10);}
 }
 c.textAlign='left';c.fillStyle='#aac4d7';c.font='bold 12px monospace';c.fillText('YÜZEY ↑  ·  '+rooms.length+' ODA  ·  4 BOSS  ·  4 BÖLGE  ·  DERİNLİK ↓',18,24);
}
function roomRouteLabel(r){const reward={ammo:'MERMİ',mod:'EKLENTİ',xp:'SİLAH XP',health:'SAĞLIK'}[r.reward]||'ÖDÜL';return roomName(r)+(r.type==='boss'?' '+r.bossStage+'/4':r.type==='start'?'':' · '+reward)+' · '+BIOMES[r.biome].name+' · LV '+r.level;}
function setMap(on){if(shopOpen||hubForgeOpen||helpOpen||!game||game.dead||game.won)return;mapOpen=on;$('mapOverlay').classList.toggle('hidden',!on);if(on){drawMap();const routes=Object.entries(currentRoom().links).map(([dir,id])=>({dir,room:game.rooms[id]}));const names={left:'SOL',right:'SAĞ',up:'YUKARI',down:'AŞAĞI'};$('mapRoute').textContent=routes.length?'KOMŞU ODALAR: '+routes.map(({dir,room})=>names[dir]+' → '+roomRouteLabel(room)).join('  |  '):'Bu odadan başka geçiş bulunmuyor.';}else canvas.focus();}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','shift','tab'].includes(k))e.preventDefault();if(k==='m'){if(shopOpen||hubForgeOpen||helpOpen)return;if(!e.repeat)setMap(!mapOpen);return;}if(k==='escape'){if(!e.repeat){if(helpOpen)closeHelp();else if(hubForgeOpen)closeHubForge();else if(shopOpen)closeShop();else if(loadoutOpen)toggleLoadout(false);else if(mapOpen)setMap(false);else togglePause();}return;}if(k==='tab'||k==='i'){if(shopOpen||hubForgeOpen||helpOpen)return;if(!e.repeat)toggleLoadout();return;}if(k==='e'&&!e.repeat)interact();if(['1','2'].includes(k)&&!e.repeat&&game&&!paused)equipSlot(Number(k)-1);if((k==='3'||k==='h')&&!e.repeat)useKit();if(k==='4'&&!e.repeat)throwGrenade();if(k==='5'&&!e.repeat)useAccessory(0);if(k==='q'&&!e.repeat)dropHeldWeapon();if(k==='r'&&!e.repeat)reloadWeapon();if(k==='v'&&!e.repeat&&game&&!paused&&!mapOpen&&shootTimer<=0)melee();if(!game||paused||mapOpen)return;const p=game.player;if((k===' '||k==='w'||k==='arrowup')&&!e.repeat&&(p.jumps<2||p.wallSide)){if(p.grapple)p.grapple=null;if(p.wallSide){p.vy=-575;p.vx=-p.wallSide*390;p.face=-p.wallSide;p.wallKick=.19;p.moveCharge=1.6;p.wallSide=0;p.jumps=1;p.grounded=false;burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#a9e6ff',13,145);sound(470,.1,'triangle');keys.add(k);return;}if(p.jumps===1){p.spin=0;p.spinDuration=.49;burst(currentRoom(),p.x+p.w/2,p.y+p.h,'#9adffd',11,160);sound(590,.1,'triangle');}p.vy=p.jumps===0?-580:-515;p.jumps++;p.grounded=false;p.dash=0;}if(k==='shift'&&!e.repeat&&p.dashCooldown<=0){burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#98e8ff',14,185);sound(310,.13,'sawtooth');p.grapple=null;p.dash=.16;p.moveCharge=1.6;p.dashCooldown=.95;p.invuln=Math.max(p.invuln,.19);game.motionTrails.push({x:p.x+p.w/2,y:p.y+p.h/2,face:p.face,life:.32,maxLife:.32,kind:'dash'});shake=Math.max(shake,3);}if(k==='z'&&!e.repeat){grappleToggle();sound(720,.07,'triangle',.014);}keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();mouse.down=false;if(game&&!paused&&!game.dead&&!game.won)togglePause();});canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;});canvas.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;canvas.focus();}});window.addEventListener('mouseup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());$('mapBtn').onclick=()=>setMap(!mapOpen);$('closeMap').onclick=()=>setMap(false);$('helpBtn').onclick=openHelp;$('startBtn').onclick=()=>{if(game?.inHub&&hubForgeOpen){applyHubForge();return;}let raw=$('seedInput').value.trim(),seed=raw?Number(raw):Math.floor(Math.random()*2147483647);if(!Number.isSafeInteger(seed)||seed<1)seed=382711;buildGame(seed>>>0);setupHub();};
for(let i=0;i<2;i++)$('slot'+(i+1)).onclick=()=>{if(game&&!paused)equipSlot(i);};$('slot3').onclick=()=>useKit();$('slot4').onclick=()=>throwGrenade();$('slot5').onclick=()=>useAccessory(0);
buildGame(Math.floor(Math.random()*2147483646)+1);setupHub();
function loop(ts){const dt=Math.min((ts-last)/1000||0,.04);last=ts;if(hitStop>0)hitStop-=dt;else update(dt);draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
window.__dropForgeDebug=()=>game?{x:game.player.x,y:game.player.y,grounded:game.player.grounded,room:game.roomId,layout:currentRoom().layout,biome:currentRoom().biome,terrain:currentRoom().terrain,difficulty:game.difficulty,mastery:{...mastery},weapons:game.player.slots.map(q=>q&&{weapon:q.weapon,mods:q.mods}),stashedMods:[...game.stashedMods],enemyCap:currentRoom().enemyCap,portals:currentRoom().portals.map(q=>({hp:q.hp,regenCap:q.regenCap,shield:q.shield,shieldCooldown:q.shieldCooldown,produced:q.produced,max:q.max}))}:null;
